public static class Revision5Checks {
    public static void Run(Action<bool,string> check,string folder){
        bool language=L.Pt;L.Pt=true;try{
        var preferences=TweakPreferences.All();check(preferences.Count<TweakCatalog.All().Count&&preferences.Count(x=>x.Multiple)>=20,"tweaks consolidate repeated controls and multi-option settings");
        check(preferences.Select(x=>x.Pt).Distinct(StringComparer.CurrentCultureIgnoreCase).Count()==preferences.Count,"tweak preference titles are unique");
