        var search=preferences.Single(p=>p.Id=="search-style");check(search.Variants.Count==4,"taskbar search uses one selector with four alternatives");var store=new MemoryRegistryStore();var searchValue=search.Variants[2].Definition;foreach(var setting in searchValue.Settings())store.Set(setting.Hive,setting.Path,setting.Name,setting.Value,setting.Kind);check(TweakPreferences.Current(search,store,26200)==search.Variants[2],"selector identifies the actual current taskbar search mode");
