        var selection=new CleanSelection(Enumerable.Range(0,5000).Select(i=>new CleanItem{Path=Path.Combine(root,"temp-"+i),Bytes=100,Source="Fixture"}));int notifications=0;selection.Changed+=()=>notifications++;selection.SetAll(true);check(selection.Count==5000&&selection.Bytes==500000&&notifications==1,"select all covers every analyzed temporary and updates the summary once");selection.Items[0].Selected=false;check(selection.Count==4999&&selection.Bytes==499900,"temporary selection totals track individual checkbox changes");selection.SetAll(false);check(selection.Count==0&&selection.Bytes==0,"clear selection resets file count and total size");
