        var old=make("delete.tmp");var busy=make("busy.tmp");var modified=make("modified.tmp");File.AppendAllText(modified.Path,"changed");string outside=Path.Combine(folder,"preserved-document.txt");File.WriteAllText(outside,"preserve");var document=new CleanItem{Path=outside,Bytes=8,Modified=DateTime.Now.AddDays(-3)};int completed=0;CleanupBatchResult outcome;using(var held=new FileStream(busy.Path,FileMode.Open,FileAccess.ReadWrite,FileShare.None))outcome=CleanupBatch.Execute(new[]{old,busy,modified,document},roots,true,(done,total,path)=>completed=done);
        check(outcome.Removed==1&&!File.Exists(old.Path)&&completed==4,"permanent temporary cleanup deletes the selected eligible file and reports progress");check(File.Exists(busy.Path)&&File.Exists(modified.Path)&&File.Exists(outside)&&outcome.Skipped==3,"permanent cleanup preserves busy files, changed files and paths outside cleanup roots");
